//! Template constructs that used to miscompile silently: exclusive
//! `elif`/`else` class branches, `if let`, ranges, tuple patterns, and string
//! literals inside double-quoted attribute values, and CSS selectors that
//! reach elements generated by `{% for %}` / `{% if %}`.

use taffy::prelude::TaffyMaxContent;
use xerune::*;

#[derive(Debug, PartialEq, XeruneMessage)]
enum Msg {
    Nop,
}

#[derive(XeruneTemplate)]
#[template(path = "tests/template_grammar.html")]
struct GrammarModel {
    on: bool,
    off: bool,
    title: String,
    cover: Option<String>,
    pairs: Vec<(String, u32)>,
    flags: Vec<bool>,
}

impl Model for GrammarModel {
    type Message = Msg;
    fn update(&mut self, _msg: Self::Message, _context: &mut Context) {}
}

struct MockMeasurer;
impl TextMeasurer for MockMeasurer {
    fn measure_text(&self, _text: &str, _font_size: f32, _weight: u16) -> (f32, f32) {
        (10.0, 10.0)
    }
}


fn texts(model: GrammarModel) -> Vec<(String, Color)> {
    let mut runtime = Runtime::new(model, MockMeasurer);
    runtime.compute_layout(taffy::geometry::Size::MAX_CONTENT);
    let mut out: Vec<_> = runtime
        .ui
        .render_data
        .values()
        .filter_map(|d| match d {
            RenderData::Text(t, style) => Some((t.to_string(), style.color)),
            _ => None,
        })
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

fn color_of(texts: &[(String, Color)], text: &str) -> Color {
    texts.iter().find(|(t, _)| t == text).unwrap_or_else(|| panic!("no text {text:?} in {texts:?}")).1
}

fn count(texts: &[(String, Color)], text: &str) -> usize {
    texts.iter().filter(|(t, _)| t == text).count()
}

fn model(on: bool, cover: Option<&str>, title: &str) -> GrammarModel {
    GrammarModel {
        on,
        off: false,
        title: title.to_string(),
        cover: cover.map(str::to_string),
        pairs: vec![("a".into(), 1), ("b".into(), 2)],
        flags: vec![true, false],
    }
}

/// The words inside `{% if red %}` are template source, not classes: a
/// variable named like the class it toggles must not switch it on for
/// every item, and `{% endif %}` must not make an ancestor match `.endif`.
#[test]
fn template_keywords_are_not_classes() {
    let t = texts(model(true, None, ""));
    let colors: Vec<Color> = t.iter().filter(|(text, _)| text == "var-named-like-class").map(|(_, c)| *c).collect();
    assert_eq!(colors.len(), 2);
    assert!(colors.contains(&Color::from_rgba8(255, 0, 0, 255)));
    assert!(colors.contains(&Color::from_rgba8(0, 0, 255, 255)));
    assert_ne!(color_of(&t, "template-keyword-not-a-class"), Color::from_rgba8(255, 0, 0, 255));
}

/// `{{ a * 10 }}` used to expand to `a * 10.to_display_string()`.
#[test]
fn arithmetic_in_text_expressions() {
    let t = texts(model(true, None, ""));
    assert_eq!(count(&t, "207"), 1, "{t:?}");
}

/// Loop variables are references (`&bool` here); a bare one used as a class
/// condition inside an element must still compile and pick the branch.
#[test]
fn bool_loop_variable_as_class_condition() {
    let t = texts(model(true, None, ""));
    let colors: Vec<Color> = t.iter().filter(|(text, _)| text == "bool-loop-var").map(|(_, c)| *c).collect();
    assert_eq!(colors.len(), 2);
    assert!(colors.contains(&Color::from_rgba8(255, 0, 0, 255)));
    assert!(colors.contains(&Color::from_rgba8(0, 0, 255, 255)));
}

#[test]
fn else_and_elif_class_branches_are_exclusive() {
    let t = texts(model(true, None, ""));
    assert_eq!(color_of(&t, "if-else"), Color::from_rgba8(255, 0, 0, 255));
    assert_eq!(color_of(&t, "elif"), Color::from_rgba8(255, 0, 0, 255));

    let t = texts(model(false, None, ""));
    assert_eq!(color_of(&t, "if-else"), Color::from_rgba8(0, 0, 255, 255));
    assert_eq!(color_of(&t, "elif"), Color::from_rgba8(0, 255, 0, 255));
}

#[test]
fn if_let_in_class_and_body() {
    let t = texts(model(false, Some("x"), ""));
    assert_eq!(color_of(&t, "if-let-class"), Color::from_rgba8(255, 0, 0, 255));
    // Text and `{{ expr }}` values form one run of text.
    assert_eq!(count(&t, "cover-x"), 1);

    let t = texts(model(false, None, ""));
    assert_eq!(color_of(&t, "if-let-class"), Color::from_rgba8(0, 0, 255, 255));
    assert!(!t.iter().any(|(s, _)| s.starts_with("cover-")));
}

#[test]
fn string_literal_inside_double_quoted_attribute() {
    assert_eq!(color_of(&texts(model(false, None, "x")), "double-quoted-literal"), Color::from_rgba8(255, 0, 0, 255));
    assert_eq!(color_of(&texts(model(false, None, "")), "double-quoted-literal"), Color::from_rgba8(0, 0, 255, 255));
}

#[test]
fn ranges_and_tuple_patterns_in_loops() {
    let t = texts(model(false, None, ""));
    assert_eq!((count(&t, "range-0"), count(&t, "range-1")), (1, 1));
    // `{{ k }}-{{ v }}-{{ loop.index }}`
    assert_eq!((count(&t, "pair-a-1-1"), count(&t, "pair-b-2-2")), (1, 1));
}

#[test]
fn selectors_match_through_loops_and_ifs() {
    let t = texts(model(true, None, ""));
    let red = Color::from_rgba8(255, 0, 0, 255);
    let blue = Color::from_rgba8(0, 0, 255, 255);
    assert!(t.iter().filter(|(s, _)| s == "loop-child").all(|(_, c)| *c == red));
    assert!(t.iter().filter(|(s, _)| s == "if-loop-descendant").all(|(_, c)| *c == blue));
    assert_eq!((count(&t, "loop-child"), count(&t, "if-loop-descendant")), (2, 2));
}
